function sha256(input) {
  const bytes = [];
  for (const char of input) {
    let cp = char.codePointAt(0);
    if (cp >= 0xD800 && cp <= 0xDFFF) cp = 0xFFFD;
    if (cp < 0x80) bytes.push(cp);
    else if (cp < 0x800) bytes.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
    else if (cp < 0x10000) bytes.push(0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F));
    else bytes.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F));
  }

  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
  ];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  bytes.push((high >>> 24) & 255,(high >>> 16) & 255,(high >>> 8) & 255,high & 255,
    (low >>> 24) & 255,(low >>> 16) & 255,(low >>> 8) & 255,low & 255);

  const rotr = (x,n) => (x >>> n) | (x << (32 - n));
  for (let offset = 0; offset < bytes.length; offset += 64) {
    const W = new Array(64);
    for (let i = 0; i < 16; i++) {
      const j = offset + i * 4;
      W[i] = ((bytes[j] << 24) | (bytes[j+1] << 16) | (bytes[j+2] << 8) | bytes[j+3]) >>> 0;
    }
    for (let i = 16; i < 64; i++) {
      const x = W[i-15], y = W[i-2];
      const s0 = rotr(x,7) ^ rotr(x,18) ^ (x >>> 3);
      const s1 = rotr(y,17) ^ rotr(y,19) ^ (y >>> 10);
      W[i] = (W[i-16] + s0 + W[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + W[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

const item = items[0].json;
const canonical = {
  canonical_url: typeof item.source_url === 'string' ? item.source_url.trim() : '',
  source_title: typeof item.source_title === 'string' ? item.source_title : '',
  publisher: typeof item.publisher === 'string' ? item.publisher : '',
  published_at: typeof item.published_at === 'string' ? item.published_at : null,
  competition: typeof item.competition === 'string' ? item.competition : '',
  teams: Array.isArray(item.teams) ? item.teams : [],
  people: Array.isArray(item.people) ? item.people : [],
  source_text: typeof item.source_text === 'string' ? item.source_text : '',
  source_type: typeof item.source_type === 'string' ? item.source_type : 'other',
  raw: item,
};
// Preserve the existing digest input exactly: selected URL (or title), NUL, published_at.
const hashInput = (canonical.canonical_url || canonical.source_title || '') + '\u0000' + (canonical.published_at || '');
canonical.source_id = 'src:' + sha256(hashInput).slice(0, 48);
return [{ json: canonical }];

// Phase 18G — duplicate stop. Re-emit canonical envelope with
// pipeline_status='duplicate'. Preserve source_* from upstream so
// MASTER sees the dedupe context.
const src = $('Normalize source').item.json || {};
const dedupe = $('POST /api/automation/deduplicate').item.json || {};
return [{
  json: {
    ...(src.raw || {}),
    run_id: dedupe.run_id || null,
    editorial_item_id: null,
    source_id: src.source_id || null,
    source_url: src.canonical_url || null,
    source_title: src.source_title || null,
    publisher: src.publisher || null,
    published_at: src.published_at || null,
    source_type: src.source_type || null,
    source_text: src.source_text || null,
    pipeline_stage: 'source_intake',
    pipeline_status: 'duplicate',
    metadata: { duplicate: true },
  },
}];

// Phase 18G — terminal promote node. Re-emits the canonical
// pipeline envelope so MASTER can extract run_id, editorial_item_id,
// and source context without losing data to the Audit-log response.
//
// Merge rule: previous envelope + fields explicitly set by this stage.
//
// Upstream payload (from POST /api/automation/editorial-item) carries
// editorial_item_id + run_id; merge with the original Normalize-source
// output which carries source_* fields.
//
// We use cross-node refs to read fields that other nodes produced.
const up = $('POST /api/automation/editorial-item').item.json;
const src = $('Normalize source').item.json || {};
return [{
  json: {
    ...(src.raw || {}),
    run_id: up.run_id || null,
    editorial_item_id: up.editorial_item_id || null,
    source_id: src.source_id || null,
    source_url: src.canonical_url || null,
    source_title: src.source_title || null,
    publisher: src.publisher || null,
    published_at: src.published_at || null,
    source_type: src.source_type || null,
    source_text: src.source_text || null,
    pipeline_stage: 'source_intake',
    pipeline_status: 'accepted',
    metadata: {},
  },
}];
